const payload = $input.first().json.body ?? $input.first().json;
const listing = payload.listing ?? {};
const description = (listing.description ?? payload.description ?? '').trim();
const agentName = (listing.agent_name ?? '').trim();
const images = listing.images ?? [];
const listingPropertyType = (listing.property_type ?? 'residential').toLowerCase();

if (!description) {
  throw new Error('listing.description is required');
}

const guardrailsInUrl = 'http://guardrails_service:8005/check/input';
const guardrailsOutUrl = 'http://guardrails_service:8005/check/output';
const ragUrl = 'http://rag_service:8001/query';
const imageAnalyserUrl = 'http://image_analyser:8002/analyse';
const agentUrl = 'http://langgraph_agent:8004/agent/run';
const triageUrl = 'http://property_triage:8003/triage';

const inputGuard = await this.helpers.httpRequest({
  method: 'POST',
  url: guardrailsInUrl,
  body: { text: description },
  json: true,
});

if (!inputGuard.pass) {
  return [{
    json: {
      status: 'blocked',
      stage: 'input_guardrails',
      source: payload.source ?? 'streamlit-webui',
      agent_name: agentName,
      listing_description: description,
      guardrails: inputGuard,
    },
  }];
}

const safeDescription = inputGuard.safe_text || description;

const [ragResult, agentResult] = await Promise.all([
  this.helpers.httpRequest({
    method: 'POST',
    url: ragUrl,
    body: { description: safeDescription },
    json: true,
  }),
  this.helpers.httpRequest({
    method: 'POST',
    url: agentUrl,
    body: { query: safeDescription },
    json: true,
  }),
]);

const imageResults = [];

if (images.length === 0) {
  const metaAnalysis = await this.helpers.httpRequest({
    method: 'POST',
    url: imageAnalyserUrl,
    body: {
      condition_description: safeDescription,
      filename: 'listing.jpg',
    },
    json: true,
  });
  imageResults.push({ filename: 'listing.jpg', analysis: metaAnalysis });
} else {
  for (const image of images) {
    const base64Data = image.data_base64 ?? '';
    if (!base64Data) {
      continue;
    }
    const buffer = Buffer.from(base64Data, 'base64');
    const filename = image.filename || 'upload.jpg';
    const contentType = image.content_type || 'image/jpeg';
    const analysisResponse = await this.helpers.httpRequest({
      method: 'POST',
      url: imageAnalyserUrl,
      formData: {
        file: {
          value: buffer,
          options: { filename, contentType },
        },
        condition_description: safeDescription,
      },
      json: true,
    });
    imageResults.push({
      filename,
      content_type: contentType,
      analysis: analysisResponse,
    });
  }
}

const combinedAnswer = [
  agentResult.answer ?? '',
  ragResult.insight ?? '',
].filter(Boolean).join(' ');

const outputGuard = await this.helpers.httpRequest({
  method: 'POST',
  url: guardrailsOutUrl,
  body: { text: combinedAnswer },
  json: true,
});

let route = listingPropertyType.includes('commercial') ? 'commercial' : 'residential';
const topListing = (ragResult.similar_listings ?? [])[0];
if (topListing?.property_type === 'commercial') {
  route = 'commercial';
} else if (topListing?.property_type === 'residential') {
  route = 'residential';
}

let triageDecision = null;
if (imageResults.length > 0 && imageResults[0].analysis?.triage_decision) {
  triageDecision = imageResults[0].analysis.triage_decision;
} else {
  triageDecision = await this.helpers.httpRequest({
    method: 'POST',
    url: triageUrl,
    body: {
      room_type: imageResults[0]?.analysis?.room_type?.replace(' (uncertain)', '') ?? 'unknown',
      condition_description: safeDescription,
    },
    json: true,
  });
}

return [{
  json: {
    status: outputGuard.pass ? 'success' : 'output_flagged',
    source: payload.source ?? 'streamlit-webui',
    agent_name: agentName,
    listing_description: safeDescription,
    pipeline: 'guardrails_rag_image_langgraph',
    route,
    property_type: route,
    input_guardrails: inputGuard,
    output_guardrails: outputGuard,
    rag_result: ragResult,
    agent_result: agentResult,
    image_results: imageResults,
    triage_decision: triageDecision,
    final_answer: outputGuard.safe_text || combinedAnswer,
  },
}];
